async function scheduleRowExists(ipnsName: string): Promise<boolean> {
  const result = await pool.query<{ count: string }>(
    'SELECT COUNT(*)::text AS count FROM ipns_republish_schedule WHERE ipns_name = $1',
    [ipnsName]
  );
